from datetime import date, timedelta

def nth_weekday(year, month, weekday, n):
    if weekday not in range(7):
        raise ValueError("weekday must be 0-6")
    if n != -1 and n not in range(1, 6):
        raise ValueError("n must be 1-5 or -1")

    first = date(year, month, 1)
    offset = (weekday - first.weekday()) % 7
    first_occurrence = first + timedelta(days=offset)

    if n == -1:
        # Last occurrence: find last day of the month, then adjust backward
        if month == 12:
            next_month = date(year + 1, 1, 1)
        else:
            next_month = date(year, month + 1, 1)
        last_day = next_month - timedelta(days=1)
        last_offset = (last_day.weekday() - weekday) % 7
        target = last_day - timedelta(days=last_offset)
        return target.isoformat()

    target = first_occurrence + timedelta(weeks=n - 1)
    if target.month != month:
        raise ValueError(f"No {n}th weekday {weekday} in {year}-{month:02d}")
    return target.isoformat()
